import{_ as t,o as a,c as n,ag as r}from"./chunks/framework.B7PviQjB.js";const o="/docs/images/docs-editor/lists-and-indents-ruler.png",m=JSON.parse('{"title":"Use lists and indents","description":"Make bulleted and numbered lists in a doc, nest list items, and set paragraph indents with the toolbar or the ruler.","frontmatter":{"title":"Use lists and indents","description":"Make bulleted and numbered lists in a doc, nest list items, and set paragraph indents with the toolbar or the ruler.","type":"how-to"},"headers":[],"relativePath":"docs-editor/lists-and-indents.md","filePath":"docs-editor/lists-and-indents.md"}'),s={name:"docs-editor/lists-and-indents.md"};function i(d,e,l,h,c,u){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="use-lists-and-indents" tabindex="-1">Use lists and indents <a class="header-anchor" href="#use-lists-and-indents" aria-label="Permalink to &quot;Use lists and indents&quot;">​</a></h1><p>Make bulleted and numbered lists, nest items under each other, and indent paragraphs.</p><h2 id="start-a-bulleted-or-numbered-list" tabindex="-1">Start a bulleted or numbered list <a class="header-anchor" href="#start-a-bulleted-or-numbered-list" aria-label="Permalink to &quot;Start a bulleted or numbered list&quot;">​</a></h2><ol><li>Put the cursor in a paragraph, or select several.</li><li>Click <strong>Bulleted list</strong> or <strong>Numbered list</strong> in the toolbar, or press <code>⌘+Shift+8</code> / <code>Ctrl+Shift+8</code> (bullets) or <code>⌘+Shift+7</code> / <code>Ctrl+Shift+7</code> (numbers).</li></ol><p>Each paragraph becomes a list item. Click the same button again to turn the items back into paragraphs.</p><h3 id="type-a-list-instead" tabindex="-1">Type a list instead <a class="header-anchor" href="#type-a-list-instead" aria-label="Permalink to &quot;Type a list instead&quot;">​</a></h3><p>At the start of an empty line, type one of these and press <code>Space</code>:</p><table tabindex="0"><thead><tr><th>Type</th><th>To get</th></tr></thead><tbody><tr><td><code>-</code> or <code>*</code></td><td>Bulleted list</td></tr><tr><td><code>1.</code></td><td>Numbered list</td></tr></tbody></table><h2 id="add-and-end-list-items" tabindex="-1">Add and end list items <a class="header-anchor" href="#add-and-end-list-items" aria-label="Permalink to &quot;Add and end list items&quot;">​</a></h2><ol><li>Press <code>Enter</code> at the end of an item to add the next one.</li><li>Press <code>Enter</code> on an empty item to end the list.</li></ol><p>The empty item turns back into a normal paragraph.</p><h2 id="nest-list-items" tabindex="-1">Nest list items <a class="header-anchor" href="#nest-list-items" aria-label="Permalink to &quot;Nest list items&quot;">​</a></h2><ol><li>Put the cursor in a list item, or select several items.</li><li>Press <code>Tab</code> to move them one level in, or <code>Shift+Tab</code> to move them one level out.</li></ol><p>A list can be up to nine levels deep. Items nested under the one you move go with it. You can also use <strong>Increase indent</strong> and <strong>Decrease indent</strong> in the toolbar.</p><h2 id="indent-a-paragraph" tabindex="-1">Indent a paragraph <a class="header-anchor" href="#indent-a-paragraph" aria-label="Permalink to &quot;Indent a paragraph&quot;">​</a></h2><ol><li>Put the cursor in the paragraph, or select several.</li><li>Click <strong>Increase indent</strong> or <strong>Decrease indent</strong> in the toolbar, or press <code>⌘+]</code> / <code>Ctrl+]</code> and <code>⌘+[</code> / <code>Ctrl+[</code>.</li></ol><p><code>Tab</code> does nothing in a plain paragraph; use these controls instead.</p><h2 id="set-indents-with-the-ruler" tabindex="-1">Set indents with the ruler <a class="header-anchor" href="#set-indents-with-the-ruler" aria-label="Permalink to &quot;Set indents with the ruler&quot;">​</a></h2><p>The ruler above the page shows the indents of the paragraph with the cursor. Units are inches or centimeters, depending on your browser&#39;s language.</p><ol><li>Put the cursor in the paragraph. The ruler changes one paragraph at a time.</li><li>To indent only the first line, drag the downward triangle (▽) at the top of the ruler.</li><li>To indent the whole paragraph, drag the upward triangle (△) at the bottom of the ruler.</li></ol><p>A guide line follows the pointer while you drag. To change page margins on the ruler instead, see <a href="/docs/docs-editor/page-layout.html">Page layout</a>.</p><p><img src="'+o+'" alt="Ruler with the first-line indent triangle half an inch in from the margin, above a paragraph indented to match"></p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>Tap ⋮ (<strong>More formatting options</strong>) at the right end of the toolbar. Under <strong>List</strong> you&#39;ll find <strong>Numbered list</strong>, <strong>Bulleted list</strong>, <strong>Decrease indent</strong>, and <strong>Increase indent</strong>. The ruler is hidden on a phone, and in any window too narrow to show the full page width, so first-line indents need a wider screen.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Each list uses its default bullet and number styles. You can&#39;t choose a bullet symbol or a starting number.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/docs-editor/format-text.html">Format text</a> for headings and paragraph styles.</li><li><a href="/docs/docs-editor/page-layout.html">Page layout</a> to change margins.</li><li><a href="/docs/docs-editor/keyboard-shortcuts.html">Keyboard shortcuts</a> for list and indent shortcuts.</li></ul>',28)])])}const g=t(s,[["render",i]]);export{m as __pageData,g as default};
